1435	                uint32_t o = pack_2x<TC>(acc_o[c*4+r*2+0] * invvd, acc_o[c*4+r*2+1] * invvd);
1436	                if (val) *reinterpret_cast<uint32_t*>(&O[obase + dv0]) = o;
1437	            }
1438	            if (tg == 0 && val) LSE[(long)qhead * total_q + qidx] = lse_v;
1439	        }
1440	    }
1441	}
