503	                "wgmma.mma_async.sync.aligned.m64n80k16.f32.bf16.bf16 " PF_ACC40 ",%40,%41,p,%43,%44,%45,%46;\n}\n"
504	                : PF_OUT40(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1),"n"(0),"n"(0));
