465	// ---- head-dim-generic helpers (HD,HDV multiples of 64; QK is m64n{CN}k16 over CN keys, k-step count
466	// = HD/16; PV is split into HDV/64 independent m64n64k16 output boxes over CN keys). CN (the key-tile
467	// width) is a template param so large head dims can use CN=64 (more smem stages fit). The Q (A) tile
468	// always has CTA_M=128 rows while the K/V (B) tiles have CN rows => the per-k-block descriptor stride
469	// differs for A vs B once HD spans >1 col-block (qk_doffR<CTA_M> vs qk_doffR<CN>). ---------------
470	template <typename T, int HDt, int CN, int CM = CTA_M>
471	__device__ __forceinline__ void qk_batch_g(float (&s)[CN/2], uint64_t baseA, uint64_t baseB, int p0) {
472	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
473	#pragma unroll
474	    for (int kb = 0; kb < HDt / 16; ++kb) {
475	        uint64_t dA = desc_add(baseA, (uint32_t)qk_doffR<CM>(kb));
476	        uint64_t dB = desc_add(baseB, (uint32_t)qk_doffR<CN>(kb));
477	        int scaleD = (kb == 0) ? p0 : 1;
478	        if constexpr (CN == 48) {
479	            if constexpr (is_f16<T>())
480	                asm volatile("{\n.reg .pred p;\n setp.ne.b32 p, %26, 0;\n"
481	                "wgmma.mma_async.sync.aligned.m64n48k16.f32.f16.f16 " PF_ACC24 ",%24,%25,p,%27,%28,%29,%30;\n}\n"
482	                : PF_OUT24(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1),"n"(0),"n"(0));
483	            else
484	                asm volatile("{\n.reg .pred p;\n setp.ne.b32 p, %26, 0;\n"
485	                "wgmma.mma_async.sync.aligned.m64n48k16.f32.bf16.bf16 " PF_ACC24 ",%24,%25,p,%27,%28,%29,%30;\n}\n"
486	                : PF_OUT24(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1),"n"(0),"n"(0));
487	        } else if constexpr (CN == 64) {
488	            if constexpr (is_f16<T>())
489	                asm volatile("{\n.reg .pred p;\n setp.ne.b32 p, %34, 0;\n"
